          fullName: "",
          emailAddress: "",
          phoneNumber: ""
        }
      };

      const fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          required: true,
          autocomplete: "name",
          placeholder: "Alex Johnson"
        },
        {
          id: "emailAddress",
          label: "Email address",
          type: "email",
          required: true,
          autocomplete: "email",
          placeholder: "alex@example.com"
        },
        {
          id: "phoneNumber",
          label: "Phone number",
          type: "tel",
          required: false,
          autocomplete: "tel",
          placeholder: "+1 (555) 123-4567",
          helpText: "Include your country code if possible, for example +1 (555) 123-4567."
        }
      ];

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function getError(id, value) {
        const trimmed = value.trim();

        if (!state.submitted && !trimmed) {
          return "";
        }

        if (id === "fullName" && !trimmed) {
          return "Full name is required.";
        }

        if (id === "emailAddress") {
          if (!trimmed) {
            return "Email address is required.";
          }

          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
            return "Enter a valid email address.";
          }
        }

        return "";
      }

      function fieldField(field) {
        const value = state.values[field.id];
        const error = getError(field.id, value);
        const errorId = `${field.id}-error`;
        const helpId = field.helpText ? `${field.id}-help` : "";
        const describedBy = [helpId, error ? errorId : ""].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">${escapeHtml(field.label)}${field.required ? " *" : ""}</label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              ${field.required ? "required" : ""}
              autocomplete="${field.autocomplete}"
              placeholder="${escapeHtml(field.placeholder)}"
              value="${escapeHtml(value)}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${error ? 'aria-invalid="true"' : ""}
            />
            ${field.helpText ? `<div class="field-help" id="${helpId}">${escapeHtml(field.helpText)}</div>` : ""}
            <div class="field-error" id="${errorId}" aria-live="polite">${escapeHtml(error)}</div>
          </div>
        `;
      }

      function render() {
        const app = document.getElementById("app");
        app.innerHTML = `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">Contact our team</h1>
            <p class="lede">Send us a message and we&apos;ll respond as soon as possible.</p>

