              <div class="form-grid">
                ${fields.map(fieldField).join("")}
              </div>
              <div class="actions">
                <button type="submit">Send message</button>
              </div>
              <p class="status" id="form-status" role="status"></p>
            </form>
          </section>
        `;

        bindEvents();
        paintForm();
      }

      function validate(values) {
        return fields.reduce((errors, field) => {
          const error = getError(field.id, values[field.id]);
          if (error) {
            errors[field.id] = error;
          }
          return errors;
        }, {});
      }

      function paintForm() {
        fields.forEach((field) => {
          const input = document.getElementById(field.id);
          const errorNode = document.getElementById(`${field.id}-error`);
          const value = state.values[field.id];
          const error = getError(field.id, value);

          input.value = value;
          input.setAttribute("aria-invalid", error ? "true" : "false");
          errorNode.textContent = error;
        });
      }

      function bindEvents() {
        const form = document.getElementById("contact-form");
        const status = document.getElementById("form-status");
        const inputs = Array.from(form.querySelectorAll("input"));

        inputs.forEach((input) => {
          input.addEventListener("input", (event) => {
            state.values[input.name] = event.target.value;
            if (state.submitted) {
              paintForm();
            }
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;

          const errors = validate(state.values);
          paintForm();

          if (Object.keys(errors).length > 0) {
            status.textContent = "";
            return;
          }

          status.textContent = "Thanks — your message has been prepared for delivery.";
          form.reset();
          state.values.fullName = "";
          state.values.emailAddress = "";
          state.values.phoneNumber = "";
          state.submitted = false;
          paintForm();
        });
      }

      render();
    </script>
  </body>
