          type: "text",
          required: true,
          autocomplete: "name",
          placeholder: "Alex Johnson"
        },
        {
          id: "emailAddress",
          label: "Email address",
          type: "email",
          required: true,
          autocomplete: "email",
          placeholder: "alex@example.com"
        },
        {
          id: "phoneNumber",
          label: "Phone number",
          type: "tel",
          required: false,
          autocomplete: "tel",
          placeholder: "+1 (555) 123-4567",
          helpText: "Include your country code if possible, for example +1 (555) 123-4567."
        }
      ];

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function getError(id, value) {
        const trimmed = value.trim();

        if (!state.submitted && !trimmed) {
