              </div>
              <p class="status" id="form-status" role="status"></p>
            </form>
          </section>
        `;

        bindEvents();
        paintForm();
      }

      function validate(values) {
        return fields.reduce((errors, field) => {
          const error = getError(field.id, values[field.id]);
          if (error) {
            errors[field.id] = error;
          }
          return errors;
